<?php
require __DIR__.'/lib.php';require_login();$lock=null;$id=(int)($_POST['id']??0);$return='wrong_returns';
try{
 if($_SERVER['REQUEST_METHOD']==='GET'&&isset($_GET['evidence'])){if(!access_page_allowed('wrong_returns'))throw new Exception('Case viewing access required.');$r=ix_case((int)$_GET['evidence']);$path=$r['evidence_path']?realpath(__DIR__.'/'.$r['evidence_path']):false;$root=realpath(__DIR__.'/uploads/return_investigations');if(!$path||!$root||!str_starts_with(str_replace('\\','/',$path),str_replace('\\','/',$root).'/'))throw new Exception('Evidence unavailable.');$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));$mime=['pdf'=>'application/pdf','png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg'][$ext]??null;if(!$mime)throw new Exception('Unsupported evidence.');header('Content-Type: '.$mime);header('X-Content-Type-Options: nosniff');header('Content-Disposition: inline; filename="Case_Evidence.'.$ext.'"');readfile($path);exit;}
 if($_SERVER['REQUEST_METHOD']!=='POST')throw new Exception('Use the inventory form.');verify_csrf();$a=$_POST['action']??'';$permission=in_array($a,['ix_damage_preview','ix_damage_post'],true)?'ix_damage':$a;ix_require($permission);$lock=inventory_write_lock();
 if($a==='ix_damage_preview'){$return='damage_declare';$plan=process_transaction(fn()=>ix_damage_plan($_POST));$_SESSION['ix_damage_preview']=['user_id'=>current_user()['id'],'token'=>bin2hex(random_bytes(32)),'key'=>hash('sha256',random_bytes(32)),'plan'=>$plan];$return.='&step=review';}
 elseif($a==='ix_damage_post'){$return='damage_declare';$s=$_SESSION['ix_damage_preview']??null;if(!$s||$s['user_id']!==current_user()['id']||!hash_equals($s['token'],(string)($_POST['token']??'')))throw new Exception('Review the declaration before confirming.');$ns=ix_damage_post($s,!empty($_POST['inspection_ack']));unset($_SESSION['ix_damage_preview']);$return='nonsellable_detail&id='.$ns;flash('Damage / leak recorded. Sellable decreased; Non-Sellable increased; total physical unchanged.');}
 elseif($a==='ix_setup'){ix_case_install();flash('Wrong item return cases enabled. No stocks changed.');}
 elseif($a==='ix_case_create'){$id=ix_case_create($_POST,$_FILES['evidence']??null);flash('Wrong item recorded for investigation / claims. No inventory credit.');$return.='&id='.$id;}
 elseif($a==='ix_case_update'){ix_case_update($id,$_POST);flash('Case status / remarks saved. No stock changed.');$return.='&id='.$id;}
 else throw new Exception('Unsupported action.');inventory_write_unlock($lock);$lock=null;header('Location: index.php?page='.$return);exit;
}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();if($lock)inventory_write_unlock($lock);flash(safe_error_message($e),'danger');if(str_starts_with($_POST['action']??'','ix_damage'))$return='damage_declare';elseif($id)$return='wrong_returns&id='.$id;header('Location: index.php?page='.$return);exit;}
